\begin{proof}
Define $\varphi:A\times B\to B\times A$ by $\varphi(a,b)=(b,a)$. This map is bijective, with inverse $\psi:B\times A\to A\times B$ given by $\psi(b,a)=(a,b)$. For $(a_1,b_1),(a_2,b_2)\in A\times B$,
\[
\begin{aligned}
\varphi\bigl((a_1,b_1)(a_2,b_2)\bigr)
&=\varphi(a_1a_2,b_1b_2)\\
&=(b_1b_2,a_1a_2)\\
&=(b_1,a_1)(b_2,a_2)\\
&=\varphi(a_1,b_1)\varphi(a_2,b_2).
\end{aligned}
\]
Thus $\varphi$ is a bijective homomorphism, so $A\times B\cong B\times A$.
\end{proof}

\begin{proof}
Let $\varphi:A\times B\to B\times A$ be defined by $\varphi(a,b)=(b,a)$. Applying the same rule twice gives the identity, so $\varphi$ is its own inverse and hence is bijective. For any $(a_1,b_1),(a_2,b_2)\in A\times B$,
\[
\begin{aligned}
\varphi\bigl((a_1,b_1)(a_2,b_2)\bigr)
&=\varphi(a_1a_2,b_1b_2)\\
&=(b_1b_2,a_1a_2)\\
&=(b_1,a_1)(b_2,a_2)\\
&=\varphi(a_1,b_1)\varphi(a_2,b_2).
\end{aligned}
\]
Therefore $\varphi$ is an isomorphism, and $A\times B\cong B\times A$.
\end{proof}
